<section class="section page-section">
  <span class="eyebrow">محاولة اختبار</span>
  <h1 class="page-title"><?= e($data['attempt']['title']) ?></h1>
  <?php if($data['is_teacher']): ?><p class="page-intro">إجابات الطالب: <?= e($data['attempt']['student_name']) ?> · الحالة: <?= e(match($data['attempt']['status']){'SUBMITTED'=>'بانتظار التصحيح','GRADED'=>'مكتمل التصحيح','INCOMPLETE'=>'غير مكتملة',default=>'قيد الأداء'}) ?></p>
    <?php foreach($data['answers'] as $answer): ?><article class="detail-card quiz-answer-review"><h2><?= nl2br(e($answer['question_text'])) ?></h2><p class="muted">الدرجة القصوى: <?= e((string)$answer['question_mark']) ?></p>
      <?php if($answer['question_type']==='ESSAY'): ?><div class="quiz-student-answer"><?= $answer['essay_answer']!==null&&$answer['essay_answer']!==''?nl2br(e($answer['essay_answer'])):'لم يجب الطالب عن هذا السؤال.' ?></div>
        <?php if($data['attempt']['status']==='SUBMITTED'&&$answer['essay_answer']!==null&&$answer['essay_answer']!==''): ?><form method="post" action="<?= e(url('quizzes')) ?>" class="quiz-grade-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="quiz_grade_essay"><input type="hidden" name="attempt_id" value="<?= (int)$data['attempt']['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$answer['question_id'] ?>"><label>الدرجة<input name="mark" type="number" min="0" max="<?= e((string)$answer['question_mark']) ?>" step="0.01" value="<?= e((string)($answer['awarded_mark']??0)) ?>" required></label><label class="quiz-wide">ملاحظة للطالب<input name="feedback" maxlength="2000" value="<?= e($answer['teacher_feedback']??'') ?>"></label><button class="button button-small">حفظ التصحيح</button></form><?php elseif($answer['awarded_mark']!==null): ?><p>الدرجة: <?= e((string)$answer['awarded_mark']) ?> / <?= e((string)$answer['question_mark']) ?></p><?php if($answer['teacher_feedback']): ?><p><?= e($answer['teacher_feedback']) ?></p><?php endif; ?><?php endif; ?>
      <?php else: ?><p>إجابة الطالب: <?= e((string)($answer['chosen_option_text']??'لم يجب')) ?></p><p>الإجابة الصحيحة: <?= e((string)$answer['correct_option_text']) ?></p><?php if($answer['is_correct']===null): ?><p>لم يُجب الطالب.</p><?php else: ?><p><?= database_bool($answer['is_correct'])?'صحيحة':'غير صحيحة' ?> · الدرجة <?= e((string)($answer['awarded_mark']??0)) ?></p><?php endif; ?><?php endif; ?>
    </article><?php endforeach; ?>
    <?php if($data['attempt']['status']==='GRADED'): ?><div class="notice">النتيجة النهائية: <?= e((string)$data['attempt']['score']) ?> من <?= e((string)$data['attempt']['total_marks']) ?> · <?= !empty($data['attempt']['result_approved_at'])?'اعتمدها المدير':'بانتظار موافقة المدير' ?></div><?php endif; ?>
    <?php if($data['is_admin'] && $data['attempt']['status']==='GRADED' && empty($data['attempt']['result_approved_at'])): ?><form method="post" action="<?= e(url('quizzes')) ?>" class="inline-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="quiz_manager_review_attempt"><input type="hidden" name="attempt_id" value="<?= (int)$data['attempt']['id'] ?>"><input type="hidden" name="decision" value="approve_result"><button class="button">اعتماد النتيجة وإظهارها للطالب</button></form><?php endif; ?>
    <?php if($data['is_admin'] && $data['attempt']['status']==='INCOMPLETE' && empty($data['attempt']['retry_granted_at'])): ?><div class="notice">المحاولة غير مكتملة. يمكن للمدير منح الطالب محاولة إضافية واحدة، وتصبح متاحة فورًا.</div><form method="post" action="<?= e(url('quizzes')) ?>" class="inline-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="quiz_manager_review_attempt"><input type="hidden" name="attempt_id" value="<?= (int)$data['attempt']['id'] ?>"><input type="hidden" name="decision" value="grant_retry"><button class="button">منح محاولة إضافية الآن</button></form><?php endif; ?>
  <?php else: ?>
    <p class="page-intro">الدرجة الكلية: <?= e((string)$data['attempt']['total_marks']) ?><?php if($data['attempt']['duration_minutes']): ?> · مدة الاختبار <?= (int)$data['attempt']['duration_minutes'] ?> دقيقة<?php endif; ?></p>
    <?php if($data['attempt']['status']==='IN_PROGRESS'): ?><?php if(!empty($data['attempt']['deadline_at'])): $deadline=new DateTimeImmutable($data['attempt']['deadline_at']); ?><p class="quiz-countdown" id="quiz-countdown" data-deadline="<?= e($deadline->format(DATE_ATOM)) ?>" aria-live="polite"></p><?php endif; ?><p class="notice">احفظ إجابتك لكل سؤال ثم سلّم الاختبار. عند انتهاء الوقت تُغلق المحاولة وفق سياسة المنصة.</p>
      <?php foreach($data['attempt']['questions'] as $index=>$question): $options=json_decode((string)$question['options'],true)?:[]; ?><article class="detail-card quiz-answer-card"><h2><?= ($index+1).'. '.e($question['question_text']) ?></h2><p class="muted">درجة السؤال: <?= e((string)$question['question_mark']) ?></p><form method="post" action="<?= e(url('quizzes')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="quiz_answer"><input type="hidden" name="attempt_id" value="<?= (int)$data['attempt']['id'] ?>"><input type="hidden" name="question_id" value="<?= (int)$question['question_id'] ?>">
        <?php if($question['question_type']==='ESSAY'): ?><label class="quiz-wide">إجابتك<textarea name="essay_answer" maxlength="10000" rows="5" required><?= e($question['essay_answer']??'') ?></textarea></label><?php else: ?><fieldset class="question-options"><legend>اختر إجابة</legend><?php foreach($options as $option): ?><label class="question-option"><input type="radio" name="selected_option_id" value="<?= (int)$option['id'] ?>" <?= (int)($question['selected_option_id']??0)===(int)$option['id']?'checked':'' ?> required><?= e($option['text']) ?></label><?php endforeach; ?></fieldset><?php endif; ?>
        <button class="button button-small">حفظ الإجابة</button></form></article><?php endforeach; ?>
      <form method="post" action="<?= e(url('quizzes')) ?>" class="quiz-submit-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="quiz_submit"><input type="hidden" name="attempt_id" value="<?= (int)$data['attempt']['id'] ?>"><button class="button" >تسليم الاختبار</button></form>
    <?php elseif($data['attempt']['status']==='SUBMITTED'): ?><div class="notice">تم استلام إجاباتك. تنتظر المحاولة اكتمال تصحيح الأستاذ.</div>
    <?php elseif($data['attempt']['status']==='INCOMPLETE'): ?><div class="notice"><?php if(!empty($data['attempt']['retry_grant_used_at'])): ?>المحاولة غير مكتملة، وقد استخدمت المحاولة الإضافية الممنوحة.<?php elseif(!empty($data['attempt']['retry_granted_at'])): ?>المحاولة غير مكتملة، وقد منحك المدير محاولة إضافية. ارجع إلى قائمة الاختبارات لبدئها الآن.<?php else: ?>المحاولة غير مكتملة لانتهاء الوقت دون تسليمها. يقرر المدير إتاحة محاولة إضافية.<?php endif; ?></div>
    <?php elseif(!$data['result_available']): ?><div class="notice">اكتمل تصحيح الاختبار، والنتيجة تنتظر موافقة المدير قبل ظهورها.</div>
    <?php else: ?><div class="notice">نتيجتك: <?= e((string)$data['attempt']['score']) ?> من <?= e((string)$data['attempt']['total_marks']) ?><?php if($data['attempt']['passing_marks']!==null): ?> · <?= (float)$data['attempt']['score'] >= (float)$data['attempt']['passing_marks']?'ناجح':'لم تبلغ درجة النجاح' ?><?php endif; ?></div><?php foreach($data['attempt']['questions'] as $question): ?><?php if($question['question_type']==='ESSAY'&&$question['awarded_mark']!==null): ?><article class="detail-card"><h2><?= e($question['question_text']) ?></h2><p>الدرجة: <?= e((string)$question['awarded_mark']) ?> / <?= e((string)$question['question_mark']) ?></p><?php if($question['teacher_feedback']): ?><p><?= e($question['teacher_feedback']) ?></p><?php endif; ?></article><?php endif; ?><?php endforeach; ?><?php endif; ?>
  <?php endif; ?>
</section>
